1	package com.example.starter.firmware.repo;
2	
3	import com.example.starter.firmware.domain.ReleaseOrder;
4	import com.example.starter.firmware.domain.ReleaseStatus;
5	import org.springframework.jdbc.core.JdbcTemplate;
6	import org.springframework.jdbc.core.RowMapper;
7	import org.springframework.jdbc.support.GeneratedKeyHolder;
8	import org.springframework.jdbc.support.KeyHolder;
9	import org.springframework.stereotype.Repository;
10	
11	import java.sql.PreparedStatement;
12	import java.util.Optional;
13	
14	/**
15	 * 发布单数据访问。扩量、取消、拉取、回执共用行锁（SELECT ... FOR UPDATE）形成一致提交顺序。
16	 */
17	@Repository
18	public class ReleaseRepository {
19	
20	    private static final RowMapper<ReleaseOrder> MAPPER = (rs, rowNum) -> new ReleaseOrder(
21	            rs.getLong("id"), rs.getInt("version"), rs.getString("model"),
22	            rs.getString("from_version"), rs.getString("to_version"),
23	            rs.getInt("ratio"), ReleaseStatus.valueOf(rs.getString("status")));
24	
25	    private static final String COLUMNS = "id, version, model, from_version, to_version, ratio, status";
26	
27	    private final JdbcTemplate jdbc;
28	
29	    public ReleaseRepository(JdbcTemplate jdbc) {
30	        this.jdbc = jdbc;
31	    }
32	
33	    public long insert(String model, String fromVersion, String toVersion, int ratio) {
34	        KeyHolder keyHolder = new GeneratedKeyHolder();
35	        jdbc.update(con -> {
36	            PreparedStatement ps = con.prepareStatement(
37	                    "INSERT INTO release_order (version, model, from_version, to_version, ratio, status, active_model)"
38	                            + " VALUES (1, ?, ?, ?, ?, 'ACTIVE', ?)",
39	                    new String[]{"id"});
40	            ps.setString(1, model);
41	            ps.setString(2, fromVersion);
42	            ps.setString(3, toVersion);
43	            ps.setInt(4, ratio);
44	            ps.setString(5, model);
