        pull("d2", "r-p2a");
        String firstWaitedAt = jdbc.queryForObject(
                "SELECT waited_at FROM region_wait_record WHERE device_id = 'd2'", String.class);
        pull("d2", "r-p2b");
        String secondWaitedAt = jdbc.queryForObject(
                "SELECT waited_at FROM region_wait_record WHERE device_id = 'd2'", String.class);
        assertThat(jdbc.queryForObject(
